package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen1Test {







    @Test
    public void testEscapeJava_SpecialCharacters() {
        // Test quotes and backslashes
        assertEquals("quote: \\\" and backslash: \\\\", StringEscapeUtils.escapeJava("quote: \" and backslash: \\"));
        // Test newlines and carriage returns
        assertEquals("line1\\nline2", StringEscapeUtils.escapeJava("line1\nline2"));
        assertEquals("line1\\r\\nline2", StringEscapeUtils.escapeJava("line1\r\nline2"));
        assertEquals("tab\\tspace", StringEscapeUtils.escapeJava("tab\tspace"));
        assertEquals("backspace\\b", StringEscapeUtils.escapeJava("backspace\b"));
        assertEquals("formfeed\\f", StringEscapeUtils.escapeJava("formfeed\f"));
    }






}

