package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen1Test {











    @Test
    public void testEscapeJava_RoundTrip() {
        // Verify that unescapeJava reverses escapeJava
        String original = "Hello \"World\"\nNew Line\tTab\\Backslash\u0001";
        String escaped = StringEscapeUtils.escapeJava(original);
        String unescaped = StringEscapeUtils.unescapeJava(escaped);
        assertEquals(original, unescaped);
    }


}

package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen1Test {













    @Test
    public void testEscapeJava_ComplexString() {
        String complex = "Mixed: \"Quotes\", \n Newlines, \t Tabs, \\ Backslashes, \u0000 Null";
        String escaped = StringEscapeUtils.escapeJava(complex);

        assertTrue(escaped.contains("\\\""));
        assertTrue(escaped.contains("\\n"));
        assertTrue(escaped.contains("\\t"));
        assertTrue(escaped.contains("\\\\"));
        assertTrue(escaped.contains("\\u0000"));
    }
}
